/**
 * Custom Workers entrypoint: OpenNext's generated fetch handler plus a
 * `scheduled` handler so the Cloudflare Cron Trigger (wrangler.jsonc
 * `triggers.crons`) can drive the daily agent tick — the Workers equivalent of
 * the old vercel.json cron hitting GET /api/tick.
 */
// @ts-expect-error — generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}

/**
 * The OpenNext bundle bakes the local `.env` (dummy/empty values) into the
 * server, and Next's env loading only skips keys ALREADY set in process.env.
 * Copy every string binding (wrangler vars + secrets) in first so the real
 * runtime config always wins over the baked file.
 */
function applyEnv(env: Env): void {
  for (const [k, v] of Object.entries(env)) {
    if (typeof v === "string") process.env[k] = v;
  }
}

export default {
  async fetch(request: Request, env: Env, ctx: unknown) {
    applyEnv(env);
    return handler.fetch(request, env, ctx);
  },

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    applyEnv(env);
    const headers = env.CRON_SECRET
      ? { authorization: `Bearer ${env.CRON_SECRET}` }
      : undefined;
    ctx.waitUntil(
      handler.fetch(new Request("https://yieldpilot.org/api/tick", { headers }), env, ctx),
    );
  },
};
